mapper.select:
SELECT * FROM ( SELECT A.*, ROWNUM as rNum FROM (
SELECT bId, bName, bTitle, bContent, bHit, bDate, fileName, bNotice, bJob, bDept, (SELECT COUNT(*) FROM reply WHERE bId = board.bId) AS replyCount FROM board
WHERE
bTitle LIKE '%' || #{keyword} || '%' bContent LIKE '%' || #{keyword} || '%' bName LIKE '%' || #{keyword} || '%'
ORDER BY NVL(bNotice, 'N') DESC, bId DESC
) A ) WHERE rNum BETWEEN #{start} AND #{end}

mapper.update:
UPDATE board 
SET bTitle = #{bTitle}, bContent = #{bContent} 
WHERE bId = #{bId}
